verify:
choices = {o: choices[n] for o, n in {'A': 'A', 'D': 'B', 'C': 'C', 'B': 'D'}.items()}; answer = {'A': 'A', 'B': 'D', 'C': 'C', 'D': 'B'}[answer]  # shuffled: original letters
def vals(s):
    s = s.replace(' only', '').replace(', and ', ' and ').replace(', ', ' and ')
    return {value(p) for p in s.split(' and ')}
x = symbols('x')
sol = set(solve(Eq((2*x - 5)*(x + 4), 0), x))
assert sol == {Rational(5, 2), -4}
assert vals(choices[answer]) == sol
assert all(vals(choices[k]) != sol for k in choices if k != answer)
